    msg: {
        error: "Expected fPort=85"
    }, 
    metadata: metadata, 
    msgType: msgType
};

// Milesight EM500-UDL
// Uplink-only telemetry decoder
// Strict ThingsBoard TBEL version
// Example payload:
// {
//     "fPort": 85,
//     "frmPayload": "A4LnHA=="
// }

var bytes = base64ToBytesList(msg.frmPayload);
var decoded = {};

var i = 0;
var length = bytes.size();
var error = null;


// -----------------------------------------------------------------------------
// Byte-reading helpers
// -----------------------------------------------------------------------------

// function u8(index) {
//     return bytes[index] & 0xFF;
// }
function u8(index) {
    return bytes.get(index) & 0xFF;
}

function readUInt16LE(index) {
    return u8(index)
        + u8(index + 1) * 256;
}

function readUInt32LE(index) {
    return u8(index)
        + u8(index + 1) * 256
        + u8(index + 2) * 65536
        + u8(index + 3) * 16777216;
}


// -----------------------------------------------------------------------------
// Value mappings
// -----------------------------------------------------------------------------

function readDistanceAlarm(value) {
    if (value == 0) {
        return "normal";
    }

    if (value == 1) {
        return "threshold_alarm";
    }

    if (value == 2) {
        return "mutation_alarm";
    }

    return "unknown";
}


// -----------------------------------------------------------------------------
// Main uplink parser
// -----------------------------------------------------------------------------

while (i < length && error == null) {

    // Every Milesight record must contain at least:
    // channel ID + channel type.
    if (i + 2 > length) {
        error = "truncated channel header at byte " + i;
        break;
    }

    var channelId = u8(i);
    var channelType = u8(i + 1);

    i = i + 2;


    // -------------------------------------------------------------------------
    // Battery
    // Channel: 01 75
    // Data: 1 byte, percentage
    // -------------------------------------------------------------------------

    if (channelId == 0x01 && channelType == 0x75) {

        if (i + 1 > length) {
            error = "truncated battery record at byte " + (i - 2);
            break;
        }

        decoded.put("battery", u8(i));

        i = i + 1;
    }


    // -------------------------------------------------------------------------
    // Distance
    // Channel: 03 82
    // Data: uint16 little-endian, unit 0.1 cm
    // -------------------------------------------------------------------------

    else if (channelId == 0x03 && channelType == 0x82) {

        if (i + 2 > length) {
            error = "truncated distance record at byte " + (i - 2);
            break;
        }

        decoded.put(
            "distance",
            readUInt16LE(i) / 10.0
        );

        i = i + 2;
    }


    // -------------------------------------------------------------------------
    // Distance alarm / mutation
    // Channel: 83 E9
    //
    // Data:
    //   bytes 0-1: distance
    //   bytes 2-3: distance mutation
    //   byte  4:   alarm status
    // -------------------------------------------------------------------------

    else if (channelId == 0x83 && channelType == 0xE9) {

        if (i + 5 > length) {
            error = "truncated distance alarm record at byte " + (i - 2);
            break;
        }

        decoded.put(
            "distance",
            readUInt16LE(i) / 10.0
        );

        decoded.put(
            "distance_mutation",
            readUInt16LE(i + 2) / 10.0
        );

        decoded.put(
            "distance_alarm",
            readDistanceAlarm(u8(i + 4))
        );

        i = i + 5;
    }


    // -------------------------------------------------------------------------
    // Historical distance record
    // Channel: 20 CE
    //
    // Data:
    //   bytes 0-3: Unix timestamp
    //   bytes 4-5: distance
    // -------------------------------------------------------------------------

    else if (channelId == 0x20 && channelType == 0xCE) {

        if (i + 6 > length) {
            error = "truncated history record at byte " + (i - 2);
            break;
        }

        var point = decodeToJson("{}");

        point.put(
            "timestamp",
            readUInt32LE(i)
        );

        point.put(
            "distance",
            readUInt16LE(i + 4) / 10.0
        );

        var history = decoded.get("history");

        if (history == null) {
            history = [];
            decoded.put("history", history);
        }

        history.push(point);

        i = i + 6;
    }


    // -------------------------------------------------------------------------
    // Unknown or unsupported uplink channel
    // -------------------------------------------------------------------------

    else {
        error =
            "unsupported uplink channel at byte "
            + (i - 2)
            + ": channel_id=0x"
            + Integer.toHexString(channelId)
            + ", channel_type=0x"
            + Integer.toHexString(channelType);
    }
}


// -----------------------------------------------------------------------------
// Error reporting
// -----------------------------------------------------------------------------

if (error != null) {
    decoded.put("error", error);
}


// -----------------------------------------------------------------------------
// Converter result
// -----------------------------------------------------------------------------

return {
    msg: decoded,
    metadata: metadata,
    msgType: msgType
};
